/* ---- src/melee/it/kinds/itfreeze.c */
void it_8028EDBC(Item_GObj* gobj)
{
    Item* ip = GET_ITEM(gobj);
    itUnkAttributes* attrs = ip->xC4_article_data->x4_specialAttributes;

    if (ip->ground_or_air != GA_Air) {
        if (ABS(ip->xDD4_itemVar.freeze.x4.x) > 0.1f) {
            if (ip->xDD4_itemVar.freeze.x0 == 0.0f) {
                if (ip->xDD4_itemVar.freeze.x4.x > 0.0f) {
                    ip->facing_dir = 1.0f;
                } else {
                    ip->facing_dir = -1.0f;
                }
                ip->xDD4_itemVar.freeze.x0 = attrs->x4_float * ip->facing_dir;
            } else {
                ip->xDD4_itemVar.freeze.x0 =
                    (ip->xDD4_itemVar.freeze.x4.x * attrs->xC) +
                    ip->xDD4_itemVar.freeze.x0;
            }
        } else {
            if (ABS(ip->xDD4_itemVar.freeze.x0) < attrs->x4_float) {
                ip->xDD4_itemVar.freeze.x0 = attrs->x4_float * ip->facing_dir;
            } else if (ip->xDD4_itemVar.freeze.x0 > 0.0f) {
                ip->xDD4_itemVar.freeze.x0 -= attrs->x10;
            } else {
                ip->xDD4_itemVar.freeze.x0 += attrs->x10;
            }
        }
        if (ip->xDD4_itemVar.freeze.x0 > attrs->x8) {
            ip->xDD4_itemVar.freeze.x0 = attrs->x8;
        } else if (ip->xDD4_itemVar.freeze.x0 < -attrs->x8) {
            ip->xDD4_itemVar.freeze.x0 = -attrs->x8;
        }
        if ((ip->xDD4_itemVar.freeze.x0 > 0.0f && ip->facing_dir < 0.0f) ||
            (ip->xDD4_itemVar.freeze.x0 < 0.0f && ip->facing_dir > 0.0f))
        {
            ip->facing_dir *= -1.0f;
        }
        ip->x40_vel.x =
            ip->xDD4_itemVar.freeze.x0 * ip->xDD4_itemVar.freeze.x4.y;
    }
}

/* ---- src/melee/it/kinds/ittaru.c */
void it_802874F0(Item_GObj* gobj)
{
    Item* ip = GET_ITEM(gobj);
    itTaruAttributes* attr = ip->xC4_article_data->x4_specialAttributes;
    f32 temp_f1;
    f32 temp_f2;
    f32 var_f0;
    int new_var2;
    f32 var_f1;
    f32 new_var;
    f32 var_f2;

    if (ip->ground_or_air != GA_Air) {
        /// @todo this surely uses some type of fabs
        /// but everything ive tried causes a reg swap
        var_f1 = ip->xDD4_itemVar.taru.xDE8.x;
        temp_f2 = var_f1;
        new_var2 = temp_f2 < 0.0f;
        if (new_var2) {
            var_f1 = -temp_f2;
        } else {
            var_f1 = temp_f2;
        }
        if (var_f1 > 0.1f) {
            var_f1 = ip->xDD4_itemVar.taru.xDE4;
            if (var_f1 < 0.0f) {
                var_f1 = -var_f1;
            }
            if (var_f1 < attr->x2C) {
                ip->xDD4_itemVar.taru.xDE4 += temp_f2 * attr->x24;
            }
        } else {
            temp_f1 = ip->xDD4_itemVar.taru.xDE4;
            if (temp_f1 < 0.0f) {
                var_f0 = -temp_f1;
            } else {
                var_f0 = temp_f1;
            }
            temp_f2 = attr->x28;
            if (var_f0 < temp_f2) {
                ip->xDD4_itemVar.taru.xDE4 = 0.0f;
            } else if (ip->xDD4_itemVar.taru.xDE4 > 0.0f) {
                ip->xDD4_itemVar.taru.xDE4 -= temp_f2;
            } else {
                ip->xDD4_itemVar.taru.xDE4 += temp_f2;
            }
        }
        temp_f2 = ip->xDD4_itemVar.taru.xDE4;
        if ((temp_f2 > 0.0f && ip->facing_dir < 0.0f) ||
            (temp_f2 < 0.0f && ip->facing_dir > 0.0f))
        {
            ip->facing_dir *= -1.0f;
        }
        var_f1 = inline_fabsf(ip->xDD4_itemVar.taru.xDE4);
        temp_f2 = attr->x20;
        if (var_f1 > temp_f2) {
            ip->xDD4_itemVar.taru.xDE4 = temp_f2 * ip->facing_dir;
        }
        ip->x40_vel.x =
            ip->xDD4_itemVar.taru.xDE4 * ip->xDD4_itemVar.taru.xDE8.y;
        var_f2 = inline_fabsf(ip->xDD4_itemVar.taru.xDE4);
        ip->xDD4_itemVar.taru.xDE0 = (0.12217305f * var_f2 * -ip->facing_dir) +
                                     ip->xDD4_itemVar.taru.xDE0;
    } else {
        ip->xDD4_itemVar.taru.xDE0 =
            (0.10471976f * -ip->facing_dir) + ip->xDD4_itemVar.taru.xDE0;
    }
}

/* ---- src/melee/it/kinds/ittarucann.c */
void it_802962E0(Item_GObj* gobj)
{
    Item* ip = GET_ITEM(gobj);
    itTaruCann_DatAttrs* da = ip->xC4_article_data->x4_specialAttributes;
    f32 temp_f1;
    f32 temp_f2;
    f32 var_f0;
    int new_var2;
    f32 var_f1;
    f32 new_var;
    f32 var_f2;
    if (ip->ground_or_air != GA_Air) {
        var_f1 = ip->xDD4_itemVar.tarucann.x14.x;
        temp_f2 = var_f1;
        new_var2 = temp_f2 < 0.0f;
        if (new_var2) {
            var_f1 = -temp_f2;
        } else {
            var_f1 = temp_f2;
        }
        if (var_f1 > 0.1f) {
            var_f1 = ip->xDD4_itemVar.tarucann.x10;
            if (var_f1 < 0.0f) {
                var_f1 = -var_f1;
            }
            if (var_f1 < da->x18) {
                ip->xDD4_itemVar.tarucann.x10 += temp_f2 * da->x10;
            }
        } else {
            temp_f1 = ip->xDD4_itemVar.tarucann.x10;
            if (temp_f1 < 0.0f) {
                var_f0 = -temp_f1;
            } else {
                var_f0 = temp_f1;
            }
            new_var = da->x14;
            var_f2 = new_var;
            if (var_f0 < var_f2) {
                ip->xDD4_itemVar.tarucann.x10 = 0.0f;
            } else {
                if (temp_f1 > 0.0f) {
                    var_f2 = -var_f2;
                }
                ip->xDD4_itemVar.tarucann.x10 = temp_f1 + var_f2;
            }
        }
        temp_f2 = ip->xDD4_itemVar.tarucann.x10;
        if ((temp_f2 > 0.0f && ip->facing_dir == -1.0f) ||
            (temp_f2 < 0.0f && ip->facing_dir == 1.0f))
        {
            ip->facing_dir = -ip->facing_dir;
        }
        var_f1 = ip->xDD4_itemVar.tarucann.x10 < 0.0f
                     ? -ip->xDD4_itemVar.tarucann.x10
                     : ip->xDD4_itemVar.tarucann.x10;
        temp_f2 = da->xC;
        if (var_f1 > temp_f2) {
            ip->xDD4_itemVar.tarucann.x10 = temp_f2 * ip->facing_dir;
        }
        ip->x40_vel.x =
            ip->xDD4_itemVar.tarucann.x28 *
            (ip->xDD4_itemVar.tarucann.x10 * ip->xDD4_itemVar.tarucann.x14.y);
        var_f2 = ip->xDD4_itemVar.tarucann.x10;
        if (var_f2 < 0.0f) {
            var_f2 = -var_f2;
        }
        ip->xDD4_itemVar.tarucann.xC +=
            ip->xDD4_itemVar.tarucann.x28 *
            (0.12217305f * var_f2 * -ip->facing_dir);
    } else {
        ip->xDD4_itemVar.tarucann.xC +=
            0.10471976f * -ip->facing_dir * ip->xDD4_itemVar.tarucann.x28;
    }
    ip->xDD4_itemVar.tarucann.xC += da->x50 * -ip->facing_dir;
}

/* ---- src/melee/it/kinds/itmewtwoshadowball.c */
bool it_2725_Logic101_Reflected(Item_GObj* gobj)
{
    Item* ip = gobj->user_data;
    ip->xDD4_itemVar.mewtwoshadowball.x4.x += M_PI;
    while (ip->xDD4_itemVar.mewtwoshadowball.x4.x < 0.0f) {
        ip->xDD4_itemVar.mewtwoshadowball.x4.x += M_TAU;
    }
    while (ip->xDD4_itemVar.mewtwoshadowball.x4.x > M_TAU) {
        ip->xDD4_itemVar.mewtwoshadowball.x4.x -= M_TAU;
    }
    return false;
}

